(function(root){'use strict';
function safe(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const colors=['#148a70','#6575de','#e3a03e','#cb689c','#459eb4','#927355'];
function chart(series,{percent=false,label='Biểu đồ metric',dayAxis=false}={}){const xs=[...new Set(series.flatMap(s=>s.points.map(p=>p.x)))].sort((a,b)=>dayAxis?Number(a)-Number(b):String(a).localeCompare(String(b))),vals=series.flatMap(s=>s.points.filter(p=>p.y!==null&&Number.isFinite(p.y)).map(p=>p.y));if(!vals.length)return '<p class="muted">Không có dữ liệu đủ thời gian quan sát trong phạm vi đã chọn.</p>';let lo=Math.min(0,...vals),hi=percent?Math.max(100,...vals):Math.max(0,...vals);if(hi===lo)hi=lo+1;const coordinate=v=>dayAxis?Number(v):(/^\d{4}-\d{2}-\d{2}$/.test(String(v))?Date.parse(v)/864e5:xs.indexOf(v)),x=v=>64+(coordinate(v)-coordinate(xs[0]))/Math.max(1,coordinate(xs.at(-1))-coordinate(xs[0]))*614,y=v=>210-(v-lo)/(hi-lo)*188;let svg='<svg class="metric-chart" viewBox="0 0 710 260" role="img" aria-label="'+safe(label)+'">';for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;svg+='<line x1="64" x2="680" y1="'+y(v)+'" y2="'+y(v)+'" stroke="#e9eef1"/><text x="3" y="'+(y(v)+4)+'">'+Number(v.toFixed(2)).toLocaleString('en')+(percent?'%':'')+'</text>'}series.forEach((s,i)=>{const color=colors[i%colors.length];let segment=[];const flush=()=>{if(segment.length)svg+='<polyline points="'+segment.join(' ')+'" fill="none" stroke="'+color+'" stroke-width="2.6"/>';segment=[]};for(const p of s.points){if(p.y===null||!Number.isFinite(p.y)){flush();continue}segment.push(x(p.x)+','+y(p.y));svg+='<circle cx="'+x(p.x)+'" cy="'+y(p.y)+'" r="3" fill="'+color+'"><title>'+safe(s.name)+' · '+(dayAxis?'R':'')+safe(p.x)+': '+p.y.toFixed(2)+(percent?'%':'')+' · n='+safe(p.n??'—')+'</title></circle>'}flush()});const tickIndexes=[...new Set([0,Math.floor((xs.length-1)/4),Math.floor((xs.length-1)/2),Math.floor(3*(xs.length-1)/4),xs.length-1])];for(const i of tickIndexes)svg+='<text x="'+x(xs[i])+'" y="247" text-anchor="'+(i===0?'start':i===xs.length-1?'end':'middle')+'">'+(dayAxis?'R':'')+safe(xs[i])+'</text>';return svg+'</svg><div class="ab-legend">'+series.map((s,i)=>'<span><i style="background:'+colors[i%colors.length]+'"></i>'+safe(s.name)+'</span>').join('')+'</div>'}
root.MetricCharts={chart};
})(typeof window!=='undefined'?window:globalThis);
